import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

// ✅ FIX 10: Read the backend URL from the environment variable.
//            When opening the app from another device on the LAN, the browser
//            is served from e.g. http://192.168.1.10:3000 but the old code had
//            "http://localhost:8080" hardcoded — that resolves to the *viewer's*
//            machine, not the machine running the backend, so WS never connects.
//            Set REACT_APP_API_URL=http://<your-LAN-IP>:8080 in .env
const BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";

class WSService {
  constructor() {
    this.client = null;
    this.subscriptions = {};   // roomId -> STOMP subscription object
    this.pendingSubs = {};     // roomId -> callback — rooms subscribed before WS connected
    this.onConnectCb = null;
    this.onDisconnectCb = null;
  }

  connect(token, onConnect, onDisconnect) {
    this.onConnectCb = onConnect;
    this.onDisconnectCb = onDisconnect;

    this.client = new Client({
      // ✅ FIX 11: Use a factory so SockJS is re-created on every reconnect attempt.
      //            Passing a single SockJS instance means after the first disconnect
      //            the closed socket is reused and the reconnect silently fails.
      webSocketFactory: () => new SockJS(`${BASE}/ws`),

      connectHeaders: { Authorization: `Bearer ${token}` },

      // Reconnect every 3 seconds on drop
      reconnectDelay: 3000,

      onConnect: () => {
        if (this.onConnectCb) this.onConnectCb();

        // ✅ FIX 12: Re-subscribe to all rooms after a reconnect.
        //            When the WebSocket drops and reconnects, all existing STOMP
        //            subscriptions are lost. Without re-subscribing, the receiver
        //            never gets new messages after any network hiccup.
        Object.entries(this.pendingSubs).forEach(([roomId, cb]) => {
          this._doSubscribe(roomId, cb);
        });
      },

      onDisconnect: () => {
        // Clear active subs — they are dead after disconnect
        this.subscriptions = {};
        if (this.onDisconnectCb) this.onDisconnectCb();
      },

      onStompError: (frame) => {
        console.error("STOMP error", frame);
      },
    });

    this.client.activate();
  }

  disconnect() {
    this.subscriptions = {};
    this.pendingSubs = {};
    if (this.client) {
      this.client.deactivate();
      this.client = null;
    }
  }

  // Internal helper — actually performs the STOMP subscribe
  _doSubscribe(roomId, callback) {
    if (!this.client?.connected) return;
    if (this.subscriptions[roomId]) return; // already subscribed

    this.subscriptions[roomId] = this.client.subscribe(
      `/topic/room/${roomId}`,
      (frame) => {
        try {
          callback(JSON.parse(frame.body));
        } catch (e) {
          console.error("Failed to parse message", e);
        }
      }
    );
  }

  // Public: subscribe to a room — works before or after connect
  subscribeRoom(roomId, callback) {
    // Always store so we can re-subscribe after reconnects
    this.pendingSubs[roomId] = callback;

    if (this.client?.connected) {
      this._doSubscribe(roomId, callback);
    }
    // If not connected yet, _doSubscribe will be called from onConnect handler
  }

  unsubscribeRoom(roomId) {
    delete this.pendingSubs[roomId];
    if (this.subscriptions[roomId]) {
      try { this.subscriptions[roomId].unsubscribe(); } catch (_) {}
      delete this.subscriptions[roomId];
    }
  }

  sendMessage(roomId, content, senderName, senderId) {
    if (!this.client?.connected) {
      console.warn("Cannot send — WebSocket not connected");
      return false;
    }
    this.client.publish({
      destination: "/app/chat.sendMessage",
      body: JSON.stringify({
        roomId,
        content,
        senderName,
        senderId,
        type: "CHAT",
      }),
    });
    return true;
  }

  get connected() {
    return !!this.client?.connected;
  }
}

// Singleton — one WS connection for the whole app
export const wsService = new WSService();
